enum WaveStageEnum { WAVE_StageBuilding, WAVE_StageStable, WAVE_StageSubsiding };
enum WavePerturbStageEnum { WAVE_PerturbStageNone, WAVE_PerturbStageDo, WAVE_PerturbStageHold, WAVE_PerturbStageCollapse, WAVE_PerturbStageWait, WAVE_PerturbStageUndo, WAVE_PerturbStageMax };
struct WaveDebugStruct {
    int AnimateBottom, AnimateFoam, BackfaceCull, BilinearFilter;
    float BoostU, BoostV;
    int BreakBigRush, BreakBigSurge, BreakBigTongue, BreakCurl, BreakFreeze, BreakLoop, BreakReload, BreakSimple, BreakStairstep, BreakRush, BreakSurge, BreakTongue, BreakTest, Clamp, ConstantResolutionX, ConstantResolutionZ, DrawClipLine, DrawDarkMesh, DrawEmitters, DrawFloater, DrawGrindPath, DrawGuideBase, DrawGuidePerturb, DrawHighMesh, DrawLightMesh, DrawMarkers, DrawProfile, DrawSoundEmitters, DrawTexture, DrawTextureAnim, DrawTubeRealLine, DrawTubeThreshs, DrawWarningLine, DrawWaveMesh, DumpMeshError, DumpProfileCoeffs, DumpProfileControls, DumpProfileMesh, DumpProfileValues, EndWave, FakeCamera, FreezeWave, MixN, MixX, MixZ, OneWave, PrintInfo, ProfileIndex;
    float ProfileWidth, ProfileYBias;
    int ReloadWave, RestartWave, ScissorWaveMesh, ScrollWater, Shadows;
    float SpeedX, SpeedZ;
    int ShowGridLines, ShowRegions, StaticWave;
};
class WaveBasePerturbClass { public: float (&duration)[WAVE_PerturbStageMax]; };
extern WaveDebugStruct WaveDebug;
extern WaveStageEnum WAVE_Stage;
extern float WAVE_StageProgress;
extern WavePerturbStageEnum WAVE_PerturbStage;
extern WaveBasePerturbClass *WAVE_Perturb;
extern int WAVE_LeftBreaker;
extern float WAVE_ShiftSpeedU, WAVE_ShiftSpeedV, WAVE_ShiftSpeedPeakU, WAVE_ShiftSpeedPeakV;
extern float WAVE_ShiftU, WAVE_ShiftV, WAVE_OffsetU, WAVE_OffsetV, WAVE_BaseOffsetU, WAVE_BaseOffsetV;
extern float WAVE_ShiftSpeedX, WAVE_ShiftSpeedZ, WAVE_ScaleU, WAVE_ScaleV, WAVE_ShiftX, WAVE_ShiftZ;
extern float TIMER_FrameSec;
inline float WAVE_GetFrameSec() { return TIMER_FrameSec; }
__asm__(".equ WaveDebug,0x004847F8");
__asm__(".equ WAVE_Stage,0x00585AD0");
__asm__(".equ WAVE_StageProgress,0x00585AD8");
__asm__(".equ WAVE_PerturbStage,0x00585C44");
__asm__(".equ WAVE_Perturb,0x0057DBD8");
__asm__(".equ WAVE_LeftBreaker,0x004846C4");
__asm__(".equ WAVE_ShiftU,0x0057EA40"); __asm__(".equ WAVE_ShiftV,0x0057EA44");
__asm__(".equ WAVE_ShiftSpeedU,0x0057EA48"); __asm__(".equ WAVE_ShiftSpeedV,0x0057EA4C");
__asm__(".equ WAVE_ShiftSpeedX,0x0057EA50"); __asm__(".equ WAVE_ShiftSpeedZ,0x0057EA54");
__asm__(".equ WAVE_ShiftSpeedPeakU,0x0057EA58"); __asm__(".equ WAVE_ShiftSpeedPeakV,0x0057EA5C");
__asm__(".equ WAVE_BaseOffsetU,0x00484648"); __asm__(".equ WAVE_BaseOffsetV,0x0048464C");
__asm__(".equ WAVE_ScaleU,0x004852CC"); __asm__(".equ WAVE_ScaleV,0x004852D0");
__asm__(".equ WAVE_OffsetU,0x004852D4"); __asm__(".equ WAVE_OffsetV,0x004852D8");
__asm__(".equ WAVE_ShiftX,0x004852DC"); __asm__(".equ WAVE_ShiftZ,0x004852E0");
__asm__(".equ TIMER_FrameSec,0x0046B280");
static void WAVE_ComputeShift(void)
{
	if (WaveDebug.StaticWave)
	{
		WAVE_ShiftSpeedU = WAVE_ShiftSpeedPeakU;
		WAVE_ShiftSpeedV = WAVE_ShiftSpeedPeakV;
	}
	else
	{
		switch (WAVE_Stage)
		{
		case WAVE_StageBuilding:
			WAVE_ShiftSpeedU = WAVE_StageProgress * WAVE_ShiftSpeedPeakU
				+ WaveDebug.BoostU * WAVE_StageProgress * (1 - WAVE_StageProgress) * WAVE_ShiftSpeedPeakU;
			WAVE_ShiftSpeedV = WAVE_StageProgress * WAVE_ShiftSpeedPeakV
				+ WaveDebug.BoostV * WAVE_StageProgress * (1 - WAVE_StageProgress) * WAVE_ShiftSpeedPeakV;
			break;
		case WAVE_StageStable:
			WAVE_ShiftSpeedU = WAVE_ShiftSpeedPeakU;
			WAVE_ShiftSpeedV = WAVE_ShiftSpeedPeakV;
			break;
		case WAVE_StageSubsiding:
			WAVE_ShiftSpeedU = (1 - WAVE_StageProgress) * WAVE_ShiftSpeedPeakU;
			WAVE_ShiftSpeedV = (1 - WAVE_StageProgress) * WAVE_ShiftSpeedPeakV;
			break;
		default:
			break;
		}

		if (!WaveDebug.BreakFreeze)
		{
			switch (WAVE_PerturbStage)
			{
			case WAVE_PerturbStageUndo:
				WAVE_ShiftSpeedU = WAVE_ShiftSpeedPeakU + WAVE_ScaleU / WAVE_Perturb->duration[WAVE_PerturbStageUndo];
				break;
			default:
				break;
			}
		}
	}

	if (WAVE_LeftBreaker)
	{
		WAVE_ShiftSpeedU = -WAVE_ShiftSpeedU;
	}

	WAVE_ShiftU += WAVE_ShiftSpeedU * WAVE_GetFrameSec();
	WAVE_ShiftU -= (int) WAVE_ShiftU;
	if ( WAVE_ShiftU < 0.0f ) WAVE_ShiftU += 1.0f;
	WAVE_OffsetU = WAVE_BaseOffsetU + WAVE_ShiftU;
	WAVE_ShiftV += WAVE_ShiftSpeedV * WAVE_GetFrameSec();
	WAVE_ShiftV -= (int) WAVE_ShiftV;
	if ( WAVE_ShiftV < 0.0f ) WAVE_ShiftV += 1.0f;
	WAVE_OffsetV = WAVE_BaseOffsetV + WAVE_ShiftV;

	WAVE_ShiftSpeedX = WAVE_ShiftSpeedU / WAVE_ScaleU;
	WAVE_ShiftSpeedZ = WAVE_ShiftSpeedV / WAVE_ScaleV;
	WAVE_ShiftX += WAVE_ShiftSpeedX * WAVE_GetFrameSec();
	WAVE_ShiftZ += WAVE_ShiftSpeedZ * WAVE_GetFrameSec();
}
